//! ♻️ Explicit native cursor lifecycle evidence preserves real terminal destructors.
use semio_framework_value_control_contract::{RetainedAllocationEffect,RetainedCloneStep,RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind,OriginalEffectReply,OriginalEffectReplyComplete,retained_clone_grant_admits};
/// 🎟️ Authorizes only the real pure destructor of an explicitly supported empty cursor header.
pub struct RetainedCursorRelease<C>{terminal:fn(&C)->bool}
impl<C> RetainedCursorRelease<C>{
 /// ⚠️ The predicate must be a pure bounded nonunwinding native query; when true, C's entire Drop must be bounded, nonallocating, callback-free and nonunwinding, with every owned payload already retired.
 pub const unsafe fn native(terminal:fn(&C)->bool)->Self{Self{terminal}}
 /// 🧷️ Checks the actual native owner against this original pure lifecycle predicate.
 pub fn validates(&self,owner:&C)->bool{(self.terminal)(owner)}
 pub fn inline_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<C>>(),depth:1,..Default::default()}}
 pub fn inline_work(&self)->u64{1}
 pub fn inline_into<'r>(&self,slot:&mut Option<C>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let Some(cursor)=slot.as_ref()else{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))};if !(self.terminal)(cursor){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"cursor header has no admitted terminal native lifecycle"))}let demand=self.inline_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"cursor header release exceeded original work")))),Err(error)=>return Ok(reply.complete(Err(error)))}drop(slot.take());Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 pub fn boxed_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<Box<C>>>(),release_bytes:std::mem::size_of::<C>(),depth:1,..Default::default()}}
 pub fn boxed_into<'r>(&self,slot:&mut Option<Box<C>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let Some(cursor)=slot.as_ref()else{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))};if !(self.terminal)(cursor){return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"boxed cursor lacks its terminal native lifecycle"))}let demand=self.boxed_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"boxed cursor release exceeded original work")))),Err(error)=>return Ok(reply.complete(Err(error)))}drop(slot.take());Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))))}

}
